#[test]
fn cstr_24h_matches_ts_golden() {
    let inf = feed();
    let mut s = inf;
    s.s_o = 0.0;
    for _ in 0..24 {
        s = step_cstr(
            &s,
            &inf,
            &PARAMS,
            CstrOptions {
                volume: 1000.0,
                flow: 100.0,
                dt_hours: 1.0,
                temperature_c: 20.0,
            },
        );
    }
    for (i, want) in CSTR.iter().enumerate() {
        let got = s.values()[i];
        assert!(
            (got - want).abs() <= 1e-12,
            "component {i}: got {got} want {want}"
        );
    }
}

#[test]
fn network_48h_matches_ts_golden() {
    let mut reactors = vec![
        Reactor {
            id: "anaerobic".into(),
            volume: 3000.0,
            state: feed(),
        },
        Reactor {
            id: "anoxic".into(),
            volume: 4500.0,
            state: feed(),
        },
        Reactor {
            id: "aerobic1".into(),
            volume: 5750.0,
            state: feed(),
        },
        Reactor {
            id: "aerobic2".into(),
            volume: 5750.0,
            state: feed(),
        },
        Reactor {
            id: "aerobic3".into(),
            volume: 5750.0,
            state: feed(),
        },
    ];
    let edges = vec![
        Edge {
            from: None,
            to: 0,
            flow: 1546.0,
            recycle: Recycle::None,
        },
        Edge {
            from: Some(4),
            to: 0,
            flow: 454.0,
            recycle: Recycle::Ras,
        },
        Edge {
            from: Some(0),
            to: 1,
            flow: 2000.0,
            recycle: Recycle::None,
        },
        Edge {
            from: Some(1),
            to: 2,
            flow: 2000.0,
            recycle: Recycle::None,
        },
        Edge {
            from: Some(2),
            to: 3,
            flow: 2000.0,
            recycle: Recycle::None,
        },
        Edge {
            from: Some(3),
            to: 4,
            flow: 2000.0,
            recycle: Recycle::None,
        },
    ];
    for _ in 0..96 {
        step_network(
            &mut reactors,
            &edges,
            &feed(),
            &PARAMS,
            NetworkOptions {
                dt_hours: 0.5,
                temperature_c: 20.0,
                x_ras: 4500.0,
            },
        );
    }
    for (ridx, reactor) in reactors.iter().enumerate() {
        for (i, want) in NETWORK[ridx].iter().enumerate() {
            let got = reactor.state.values()[i];
            assert!(
                (got - want).abs() <= 1e-12,
                "reactor {ridx} component {i}: got {got} want {want}"
            );
        }
    }
}
